def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # A colored horizontal run followed by a uniform contrasting tail has
        # its tail marked with 1. Fully filled rows remain unchanged.
        if len(row) < 2:
            continue
        first = row[0]
        k = 1
        while k < len(row) and row[k] == first:
            k += 1
        if 0 < k < len(row) and len(set(row[k:])) == 1 and row[k] != first:
            out[r][k:] = [1] * (len(row) - k)
    return out
